import { describe, expect, it } from 'vitest';
import { briefProblems, directionProblems } from '@/lib/domain/creative-direction';
import { CREATIVE_DEMOS, creativeDemoPack, demoMarkdown, generateCreativeDemoDocuments } from '@/lib/domain/creative-demos';

// The three flagship demonstrations are generated by the real engine. These assertions keep the
// documents honest: valid briefs, three different concepts, no placeholders and no real client data.

describe('the flagship creative demonstrations', () => {
  const pack = creativeDemoPack();

  it('covers a tailoring atelier, a boutique hotel and an architecture studio', () => {
    expect(CREATIVE_DEMOS).toHaveLength(3);
    expect(CREATIVE_DEMOS.map((demo) => demo.slug)).toEqual(['nsroma-atelier', 'adwoas-house', 'bantama-design-office']);
    expect(CREATIVE_DEMOS.map((demo) => demo.business.category)).toEqual(
      expect.arrayContaining(['Fashion and tailoring', 'Boutique hotel and resort', 'Architecture and interior design studio']),
    );
  });

  it('produces a valid brief and three distinct concepts for every business', () => {
    for (const result of pack) {
      expect(briefProblems(result.brief, result.assets), result.demo.slug).toEqual([]);
      expect(directionProblems(result.direction, result.brief, result.assets), result.demo.slug).toEqual([]);
      expect(result.direction.concepts).toHaveLength(3);
      expect(new Set(result.direction.concepts.map((concept) => concept.composition.family)).size).toBe(3);
      expect(new Set(result.direction.concepts.map((concept) => `${concept.typography.displayFontId}+${concept.typography.bodyFontId}`)).size).toBe(3);
      expect(new Set(result.direction.concepts.map((concept) => concept.story.premise)).size).toBe(3);
      expect(result.direction.concepts.every((concept) => concept.quality.dimensions.length === 12)).toBe(true);
      expect(result.brief.provenance.verified).toBeGreaterThan(0);
      expect(result.brief.missingInformation.some((item) => item.blocking || item.source === 'language')).toBe(true);
    }
  });

  it('does not recycle one palette-and-font template across the businesses', () => {
    const signatures = pack.map((result) => ({
      slug: result.demo.slug,
      concepts: result.direction.concepts.map((concept) => `${concept.composition.family}|${concept.typography.displayFontId}|${concept.colour.palette.find((entry) => entry.role === 'background')?.hex}`),
    }));
    const pairs = signatures.flatMap((entry) => entry.concepts);
    expect(new Set(pairs).size).toBeGreaterThanOrEqual(8);
    expect(signatures[0].concepts).not.toEqual(signatures[1].concepts);
    expect(signatures[1].concepts).not.toEqual(signatures[2].concepts);
  });

  it('writes complete Markdown without placeholders or undefined values', () => {
    const documents = generateCreativeDemoDocuments();
    expect(documents).toHaveLength(3);
    for (const [index, document] of documents.entries()) {
      expect(document.markdown.startsWith(`# ${CREATIVE_DEMOS[index].business.name}`)).toBe(true);
      expect(document.markdown).toContain('## Creative Direction Brief');
      expect(document.markdown).toContain('## 1.');
      expect(document.markdown).toContain('## 2.');
      expect(document.markdown).toContain('## 3.');
      expect(document.markdown).toContain('Advisory only.');
      expect(document.markdown).toContain('SIL Open Font License 1.1');
      expect(document.markdown).not.toContain('undefined');
      expect(document.markdown).not.toContain('NaN');
      expect(document.markdown.length).toBeGreaterThan(8000);
    }
    expect(demoMarkdown(pack[1])).toContain("Adwoa's House");
    expect(demoMarkdown(pack[2])).toContain('Bantama Design Office');
  });
});
